/**
 * A.10 — Crystal Bodies.
 * Actual triangulated 3D solid volume derived from the SAME persistent growth
 * state as the 2D studio. Each occupied coarse grid-cell contributes a raised
 * top and its exposed boundary walls; nothing is generated by screen-space
 * shader noise or the passage of time.
 *
 * Material shading is expressive: Fresnel-like edge light, spectral channel
 * separation and exponential absorption are artist approximations. This is
 * NOT ray-traced refraction, physically calibrated index of refraction,
 * 3D phase-field crystallization, or arbitrary tetrahedral volume growth.
 *
 * Designed for self-contained HTML: WebGL2 used only if supported; the normal
 * Canvas2D studio remains available with unchanged geometry and controls.
 */
const TAU_BODY = Math.PI * 2;
const boundBody = (v,a,b) => Math.max(a,Math.min(b,v));

/** Derive a real 3D surface and boundary walls from ALL four growth families. */
export function buildCrystalMesh(world,{depth=.72,detail='balanced'}={}){
  const step=detail==='fine'?2:detail==='fast'?6:4;
  const grid=Math.ceil(world.size/step),count=grid*grid;
  const id=new Uint8Array(count),density=new Float32Array(count);
  const age=new Float32Array(count),axis=new Float32Array(count),ring=new Float32Array(count);
  let occupied=0;
  const phase=world.phase,spher=world.spherulite;
  for(let gy=0;gy<grid;gy++)for(let gx=0;gx<grid;gx++){
    const votes=new Uint16Array(Math.max(2,world.grains.length+1));
    let samples=0;
    for(let y=gy*step;y<Math.min(world.size,(gy+1)*step);y++){
      for(let x=gx*step;x<Math.min(world.size,(gx+1)*step);x++){
        const g=world.crystal[y*world.size+x];
        if(g && g<votes.length){votes[g]++;samples++;}
      }
    }
    if(!samples)continue;
    let dominant=0,maximum=0;
    for(let k=1;k<votes.length;k++)if(votes[k]>maximum){maximum=votes[k];dominant=k;}
    if(!dominant)continue;
    const i=gy*grid+gx,g=world.grains[dominant-1];
    id[i]=dominant;density[i]=samples/(Math.min(step,world.size-gx*step)*Math.min(step,world.size-gy*step));occupied++;
    const wx=Math.min(world.size-1,Math.floor((gx+.5)*step));
    const wy=Math.min(world.size-1,Math.floor((gy+.5)*step));
    const px=boundBody(Math.floor(wx/phase.scale),0,phase.size-1);
    const py=boundBody(Math.floor(wy/phase.scale),0,phase.size-1);
    const sx=boundBody(Math.floor(wx/spher.scale),0,spher.size-1);
    const sy=boundBody(Math.floor(wy/spher.scale),0,spher.size-1);
    const pi=py*phase.size+px,si=sy*spher.size+sx;
    if(spher.owner[si]===dominant){
      age[i]=spher.birth[si]||world.ticks;
      axis[i]=spher.director[si];ring[i]=spher.ring[si];
    }else if(phase.owner[pi]===dominant){
      age[i]=phase.birth[pi]||world.ticks;
      axis[i]=g.angle;
      ring[i]=Math.sin((age[i]-g.seededAt)*.05);
    }else{
      age[i]=world.ticks*.35 + (wx+wy)*.06;
      axis[i]=g?.angle||0;
      ring[i]=Math.sin((wx*.12+wy*.09+dominant)*1.3);
    }
  }
  // Interior distance is computed from real occupied morphology: convex ridges
  // rise where matter becomes wide; narrow dendrites stay knife-like.
  const d=new Float32Array(count),diag=1.41421356237;
  for(let y=0;y<grid;y++)for(let x=0;x<grid;x++){
    const i=y*grid+x;
    d[i]=id[i]&&x&&y&&x<grid-1&&y<grid-1&&id[i-1]&&id[i+1]&&id[i-grid]&&id[i+grid]?10000:0;
  }
  for(let y=1;y<grid-1;y++)for(let x=1;x<grid-1;x++){
    const i=y*grid+x;if(!d[i])continue;
    d[i]=Math.min(d[i],d[i-1]+1,d[i-grid]+1,d[i-grid-1]+diag,d[i-grid+1]+diag);
  }
  for(let y=grid-2;y>=1;y--)for(let x=grid-2;x>=1;x--){
    const i=y*grid+x;if(!d[i])continue;
    d[i]=Math.min(d[i],d[i+1]+1,d[i+grid]+1,d[i+grid+1]+diag,d[i+grid-1]+diag);
  }
  const height=new Float32Array(count);
  for(let i=0;i<count;i++)if(id[i]){
    const ridge=1-Math.exp(-d[i]*.27);
    const layer=.5+.5*Math.cos(age[i]*.057 +ring[i]*2.0);
    // The third dimension is an extrusion/relief of the 2D simulation,
    // influenced by real thickness of local material and growth chronology.
    height[i]=(.045+depth*(.13 + .43*ridge + .10*layer))*(.67+.33*Math.sqrt(density[i]));
  }
  const verts=[];let topTriangles=0,wallTriangles=0,bottomTriangles=0;
  function addTriangle(a,b,c,tone,history,band){
    const ab=[b[0]-a[0],b[1]-a[1],b[2]-a[2]],ac=[c[0]-a[0],c[1]-a[1],c[2]-a[2]];
    let nx=ab[1]*ac[2]-ab[2]*ac[1],ny=ab[2]*ac[0]-ab[0]*ac[2],nz=ab[0]*ac[1]-ab[1]*ac[0];
    const length=Math.hypot(nx,ny,nz)||1;nx/=length;ny/=length;nz/=length;
    for(const v of [a,b,c])verts.push(v[0],v[1],v[2],nx,ny,nz,tone,history,band);
  }
  function addQuad(a,b,c,d,t,h,bottom){addTriangle(a,b,c,t,h,bottom);addTriangle(a,c,d,t,h,bottom);}
  function at(x,y){return x<0||y<0||x>=grid||y>=grid?-1:y*grid+x;}
  function topAt(cx,cy,center){
    let total=0,num=0;
    for(let yy=cy-1;yy<=cy;yy++)for(let xx=cx-1;xx<=cx;xx++){
      const i=at(xx,yy);
      if(i>=0&&id[i]){total+=height[i];num++;}
    }
    return num?total/num:0; // Shared corner heights prevent cracks between adjacent facets.
  }
  for(let y=0;y<grid;y++)for(let x=0;x<grid;x++){
    const i=y*grid+x;if(!id[i])continue;
    const x0=x/grid*2-1,x1=(x+1)/grid*2-1,y0=1-y/grid*2,y1=1-(y+1)/grid*2;
    const h00=topAt(x,y,i),h10=topAt(x+1,y,i),h11=topAt(x+1,y+1,i),h01=topAt(x,y+1,i);
    const a=[x0,y0,h00],b=[x1,y0,h10],c=[x1,y1,h11],e=[x0,y1,h01];
    const tone=((id[i]*.151+age[i]*.0027+ring[i]*.135+axis[i]/TAU_BODY*.19)%1+1)%1;
    const history=((age[i]*.011)%1+1)%1;
    addQuad(a,e,c,b,tone,history,ring[i]);topTriangles+=2;
    const bottom=[x0,y0,-.027],bt1=[x1,y0,-.027],bt2=[x1,y1,-.027],bt3=[x0,y1,-.027];
    addQuad(bottom,bt1,bt2,bt3,tone,history,ring[i]);bottomTriangles+=2;
    // True side walls make the shapes volumetric in profile; exposed borders
    // remain open to other colonies instead of bridging forbidden crystal cells.
    if(y===0||!id[i-grid]){addQuad(a,b,bt1,bottom,tone,history,ring[i]);wallTriangles+=2;}
    if(x===grid-1||!id[i+1]){addQuad(b,c,bt2,bt1,tone,history,ring[i]);wallTriangles+=2;}
    if(y===grid-1||!id[i+grid]){addQuad(c,e,bt3,bt2,tone,history,ring[i]);wallTriangles+=2;}
    if(x===0||!id[i-1]){addQuad(e,a,bottom,bt3,tone,history,ring[i]);wallTriangles+=2;}
  }
  // A.11: append independent three-dimensional voxel growth. The old 2D
  // extrusion remains fully reversible and is unchanged for non-volume art.
  const volume=world.volume?.active?buildVolumeMesh(world.volume,{depth}):null;
  const oldVertices=verts.length,combined=new Float32Array(oldVertices+(volume?.vertices.length||0));
  combined.set(verts);
  if(volume)combined.set(volume.vertices,oldVertices);
  return {vertices:combined,stride:9,grid,step,occupied,topTriangles,wallTriangles,bottomTriangles,
    volumeVoxels:volume?.voxels||0,volumeFaces:volume?.exposedFaces||0,volumeTriangles:volume?.triangles||0,
    triangles:combined.length/27,depth,detail,heights:height,owners:id};
}

/** Real Z-resolved 3D mesh: six exposed faces per occupied voxel, with angular
 * face centers that add facet normals. Unlike old 2D extrusion, shape and
 * internal cavities come from distinct x/y/z material occupancy. */
export function buildVolumeMesh(volume,{depth=.72}={}){
  const n=volume.size, a=volume.area;
  const vertices=[];let exposedFaces=0,grainBoundaries=0;
  const paletteTone=(g,age,z)=>((g*.167 + age*.0032 + z/n*.18)%1+1)%1;
  function triangle(v0,v1,v2,pigment,history,band){
    const u=[v1[0]-v0[0],v1[1]-v0[1],v1[2]-v0[2]],v=[v2[0]-v0[0],v2[1]-v0[1],v2[2]-v0[2]];
    let nx=u[1]*v[2]-u[2]*v[1],ny=u[2]*v[0]-u[0]*v[2],nz=u[0]*v[1]-u[1]*v[0];
    const d=Math.hypot(nx,ny,nz)||1;nx/=d;ny/=d;nz/=d;
    for(const p of [v0,v1,v2])vertices.push(p[0],p[1],p[2],nx,ny,nz,pigment,history,band);
  }
  // The center of each exposed square is pushed along its outward 3D normal.
  // Border corners remain continuous; adjacent faces form real, hard facets.
  const sides=[
    {d:[1,0,0],face:[1,2,6,5]}, {d:[-1,0,0],face:[0,4,7,3]},
    {d:[0,1,0],face:[2,3,7,6]}, {d:[0,-1,0],face:[0,1,5,4]},
    {d:[0,0,1],face:[4,5,6,7]}, {d:[0,0,-1],face:[0,3,2,1]},
  ];
  let voxels=0;
  for(let z=1;z<n-1;z++)for(let y=1;y<n-1;y++)for(let x=1;x<n-1;x++){
    const i=z*a+y*n+x,g=volume.owner[i];if(!g)continue;
    voxels++;
    const center=[(x+.5)/n*2-1,1-(y+.5)/n*2,((z+.5)/n*2-1)*(.82+.17*depth)];
    const r=1/n;
    const corners=[[-r,r,-r],[r,r,-r],[r,-r,-r],[-r,-r,-r],[-r,r,r],[r,r,r],[r,-r,r],[-r,-r,r]].map(c=>[center[0]+c[0],center[1]+c[1],center[2]+c[2]*(.82+.17*depth)]);
    const tone=paletteTone(g,volume.birth[i],z),history=(volume.birth[i]*.009)%1,band=z/n;
    for(const side of sides){
      const xx=x+side.d[0],yy=y+side.d[1],zz=z+side.d[2];
      const neighbor=volume.owner[zz*a+yy*n+xx];
      if(neighbor===g)continue;
      if(neighbor&&neighbor!==g){grainBoundaries++;continue;} // no internal opaque wall between touching grains
      const v=side.face.map(j=>corners[j]);
      const mid=v[0].map((_,j)=>(v[0][j]+v[1][j]+v[2][j]+v[3][j])/4);
      // Small true three-axis facet; no geometry depends on a shader clock.
      const lift=r*(.12+.25*depth);
      for(let j=0;j<3;j++)mid[j]+=side.d[j]*lift;
      for(let j=0;j<4;j++)triangle(v[(j+1)%4],v[j],mid,tone,history,band);
      exposedFaces++;
    }
  }
  return {vertices:new Float32Array(vertices),voxels,exposedFaces,grainBoundaries,triangles:vertices.length/27};
}

const VERT_BODY=`#version 300 es
precision highp float;
layout(location=0) in vec3 aPos;
layout(location=1) in vec3 aNormal;
layout(location=2) in vec3 aPigment;
uniform float uYaw,uTilt,uZoom;
out vec3 vNormal;
out vec3 vPigment;
out vec3 vPosition;
void main(){
  float cy=cos(uYaw),sy=sin(uYaw),ct=cos(uTilt),st=sin(uTilt);
  vec3 p=vec3(aPos.xy,aPos.z-.12);
  float x=cy*p.x-sy*p.y,y=sy*p.x+cy*p.y;
  float projectedY=ct*y-st*p.z;
  float depth=st*y+ct*p.z;
  gl_Position=vec4(x*uZoom,projectedY*uZoom,-depth*.52,1.);
  vNormal=aNormal;vPigment=aPigment;vPosition=aPos;
}`;
const FRAG_BODY=`#version 300 es
precision highp float;
in vec3 vNormal,vPigment,vPosition;
out vec4 frag;
uniform sampler2D uPalette;
uniform float uLightAngle,uAbsorption,uDispersion,uTransparency,uLayerBands,uYaw,uTilt;
const float TAU=6.28318530718;
void main(){
  vec3 n=normalize(vNormal);
  vec3 L=normalize(vec3(cos(uLightAngle),sin(uLightAngle),.78));
  vec3 V=normalize(vec3(-sin(uYaw)*sin(uTilt),cos(uYaw)*sin(uTilt),cos(uTilt)));
  float diffuse=max(dot(n,L),0.);
  float rim=pow(1.-abs(dot(n,V)),2.8);
  float face=max(0.,dot(normalize(L+V),n));
  float spec=pow(face,24.);
  float dark=exp(-uAbsorption*(.35+vPosition.z*.8));
  float layer=(.5+.5*cos(TAU*(vPigment.y*4.0+vPosition.z*2.8)))*uLayerBands;
  float base=fract(vPigment.x+layer*.075);
  float shift=uDispersion*(.035+rim*.09+max(vPosition.z,0.)*.025);
  vec3 pigment=vec3(
    texture(uPalette,vec2(fract(base-shift),.5)).r,
    texture(uPalette,vec2(base,.5)).g,
    texture(uPalette,vec2(fract(base+shift),.5)).b
  );
  float shading=(.20+.83*diffuse)*dark;
  vec3 color=pigment*shading+vec3(.74,.84,1.)*(spec*.52+rim*(.11+.5*uDispersion));
  color+=pigment*(.18*layer);
  float opacity=1.-uTransparency*(.22+.4*rim);
  frag=vec4(clamp(color,0.,1.),clamp(opacity,.31,1.));
}`;
function makeShaderBody(gl,kind,source){
  const sh=gl.createShader(kind);gl.shaderSource(sh,source);gl.compileShader(sh);
  if(!gl.getShaderParameter(sh,gl.COMPILE_STATUS)){
    const message=gl.getShaderInfoLog(sh);gl.deleteShader(sh);throw Error(`Crystal Body shader: ${message}`);
  }return sh;
}
/** Actual GPU triangle renderer with cached physics-derived mesh. */
export class CrystalBodyGPU{
  constructor(createCanvas,initialSize=700){
    this.canvas=createCanvas();this.canvas.width=this.canvas.height=initialSize;
    const gl=this.canvas.getContext('webgl2',{alpha:true,antialias:true,depth:true,premultipliedAlpha:false,preserveDrawingBuffer:true});
    if(!gl)throw Error('WebGL2 crystal body view unavailable');
    this.gl=gl;this.program=gl.createProgram();
    const v=makeShaderBody(gl,gl.VERTEX_SHADER,VERT_BODY),f=makeShaderBody(gl,gl.FRAGMENT_SHADER,FRAG_BODY);
    gl.attachShader(this.program,v);gl.attachShader(this.program,f);gl.linkProgram(this.program);
    if(!gl.getProgramParameter(this.program,gl.LINK_STATUS))throw Error('Crystal Body link: '+gl.getProgramInfoLog(this.program));
    gl.deleteShader(v);gl.deleteShader(f);
    this.vao=gl.createVertexArray();gl.bindVertexArray(this.vao);
    this.vbo=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,this.vbo);
    const stride=9*4;
    for(const [location,size,offset] of [[0,3,0],[1,3,12],[2,3,24]]){
      gl.enableVertexAttribArray(location);gl.vertexAttribPointer(location,size,gl.FLOAT,false,stride,offset);
    }
    this.paletteTexture=gl.createTexture();this.lastPalette=-1;this.lastGeometry=-1;this.lastDetail='';this.lastDepth=-1;
    this.vertices=0;this.triangles=0;this.status='ready';this.mesh=null;this.lost=false;
    this.uniforms=Object.fromEntries(['uPalette','uYaw','uTilt','uZoom','uLightAngle','uAbsorption','uDispersion','uTransparency','uLayerBands'].map(k=>[k,gl.getUniformLocation(this.program,k)]));
    this.canvas.addEventListener('webglcontextlost',ev=>{ev.preventDefault();this.lost=true;});
  }
  updateGeometry(world,settings={},now=0){
    const geometryVersion=world.modified;
    if(this.lastGeometry===geometryVersion&&this.lastDetail===settings.detail&&this.lastDepth===settings.depth)return;
    // Limit mesh rebuilding for continuously growing worlds on older iPhones.
    if(this.lastGeometry!==-1&&this.lastDetail===settings.detail&&this.lastDepth===settings.depth&&now-this.lastBuildAt<145)return;
    const mesh=buildCrystalMesh(world,settings);
    const gl=this.gl;gl.bindBuffer(gl.ARRAY_BUFFER,this.vbo);gl.bufferData(gl.ARRAY_BUFFER,mesh.vertices,gl.DYNAMIC_DRAW);
    this.mesh=mesh;this.vertices=mesh.vertices.length/9;this.triangles=mesh.triangles;
    this.lastGeometry=geometryVersion;this.lastDetail=settings.detail;this.lastDepth=settings.depth;this.lastBuildAt=now;
  }
  updatePalette(lut,revision){
    if(this.lastPalette===revision)return;
    const gl=this.gl;
    const pixels=new Uint8Array(256*4);
    for(let k=0;k<256;k++){pixels[k*4]=lut[k*3];pixels[k*4+1]=lut[k*3+1];pixels[k*4+2]=lut[k*3+2];pixels[k*4+3]=255;}
    gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,this.paletteTexture);
    gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MIN_FILTER,gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_MAG_FILTER,gl.LINEAR);
    gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_S,gl.REPEAT);
    gl.texParameteri(gl.TEXTURE_2D,gl.TEXTURE_WRAP_T,gl.CLAMP_TO_EDGE);
    gl.texImage2D(gl.TEXTURE_2D,0,gl.RGBA8,256,1,0,gl.RGBA,gl.UNSIGNED_BYTE,pixels);
    this.lastPalette=revision;
  }
  render(world,lut,revision,settings,now=0,outputSize=700){
    if(this.lost)throw Error('WebGL2 context lost');
    this.updateGeometry(world,settings,now);this.updatePalette(lut,revision);
    const gl=this.gl, size=boundBody(Math.round(outputSize),1,Math.min(4096,gl.getParameter(gl.MAX_RENDERBUFFER_SIZE)));
    if(this.canvas.width!==size||this.canvas.height!==size){this.canvas.width=this.canvas.height=size;}
    gl.viewport(0,0,size,size);gl.enable(gl.DEPTH_TEST);gl.depthFunc(gl.LEQUAL);
    gl.enable(gl.BLEND);gl.blendFunc(gl.SRC_ALPHA,gl.ONE_MINUS_SRC_ALPHA);
    gl.disable(gl.CULL_FACE);gl.clearColor(0,0,0,0);gl.clearDepth(1);gl.clear(gl.COLOR_BUFFER_BIT|gl.DEPTH_BUFFER_BIT);
    gl.useProgram(this.program);gl.bindVertexArray(this.vao);
    gl.activeTexture(gl.TEXTURE0);gl.bindTexture(gl.TEXTURE_2D,this.paletteTexture);
    gl.uniform1i(this.uniforms.uPalette,0);
    gl.uniform1f(this.uniforms.uYaw,settings.yaw??.2);
    gl.uniform1f(this.uniforms.uTilt,settings.tilt??.58);
    gl.uniform1f(this.uniforms.uZoom,settings.zoom??.73);
    gl.uniform1f(this.uniforms.uLightAngle,(settings.lightAngle??315)*Math.PI/180);
    gl.uniform1f(this.uniforms.uAbsorption,settings.absorption??.28);
    gl.uniform1f(this.uniforms.uDispersion,settings.dispersion??.6);
    gl.uniform1f(this.uniforms.uTransparency,settings.transparency??.12);
    gl.uniform1f(this.uniforms.uLayerBands,settings.bands??.52);
    gl.drawArrays(gl.TRIANGLES,0,this.vertices);
    if(gl.getError()!==gl.NO_ERROR)throw Error('Crystal Body GL draw error');
    return this.canvas;
  }
  dispose(){
    const gl=this.gl;if(!gl)return;
    gl.deleteBuffer(this.vbo);gl.deleteTexture(this.paletteTexture);gl.deleteVertexArray(this.vao);gl.deleteProgram(this.program);
  }
}
